#!/usr/bin/env python3
"""Local extraction and quotation-provenance gate; no network calls."""
import argparse
import csv
import hashlib
import io
import json
from pathlib import Path
import re
import sys

FIELDS = ["citation", "page", "quoted_passage", "claim", "limitation", "claim_type"]


def reader(data):
    try:
        from pypdf import PdfReader
    except ImportError:
        raise SystemExit("Missing pypdf. Use a Python environment with pypdf installed.")
    return PdfReader(io.BytesIO(data))


def digest(data):
    return hashlib.sha256(data).hexdigest()


def normalized(text):
    return re.sub(r"\s+", " ", text).strip()


def json_write(path, value):
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def source_path(root, citation):
    path = root / citation
    if Path(citation).is_absolute() or not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Citation must remain inside the supplied PDF folder")
    return path


def extract(args):
    root = args.source.resolve()
    work = args.work.resolve()
    if not root.is_dir():
        raise SystemExit("Supplied PDF folder does not exist")
    if work == root or work.is_relative_to(root):
        raise SystemExit("Use a work folder outside the supplied PDF folder")
    if (work / "pages.json").exists():
        raise SystemExit("pages.json already exists; use a fresh work folder")
    work.mkdir(parents=True, exist_ok=True)
    files = sorted(p for p in root.rglob("*") if p.is_file() and p.suffix.lower() == ".pdf")
    issues, sources = [], {}
    for path in files:
        citation = path.relative_to(root).as_posix()
        record = {"sha256": None, "page_count": None, "pages": []}
        sources[citation] = record
        try:
            path = source_path(root, citation)
            data = path.read_bytes()
            record["sha256"] = digest(data)
            pdf = reader(data)
            if pdf.is_encrypted and not pdf.decrypt(""):
                raise ValueError("Password-protected PDF; no readable pages")
            record["page_count"] = len(pdf.pages)
            for index, page in enumerate(pdf.pages, 1):
                try:
                    text = page.extract_text() or ""
                    status = "readable" if normalized(text) else "no_extractable_text"
                    record["pages"].append({"page": index, "status": status, "text": text})
                    if status != "readable":
                        issues.append([citation, index, status, "May be blank or scanned; not verified readable"])
                except Exception as error:
                    record["pages"].append({"page": index, "status": "extraction_error", "text": ""})
                    issues.append([citation, index, "extraction_error", str(error)])
        except Exception as error:
            issues.append([citation, "", "unreadable_pdf", str(error)])
    for citation in args.expected:
        if citation not in sources:
            issues.append([citation, "", "missing_pdf", "Expected PDF was not found in supplied folder"])
    if not files:
        issues.append(["", "", "no_pdfs", "No PDFs found"])
    json_write(work / "pages.json", {"schema": 1, "source_root": str(root), "sources": sources})
    with (work / "issues.csv").open("w", encoding="utf-8", newline="") as stream:
        writer = csv.writer(stream)
        writer.writerow(["citation", "page", "issue", "detail"])
        writer.writerows(issues)
    print(json.dumps({"pdfs": len(sources), "issues": len(issues), "work": str(work)}))


def verify(args):
    manifest = json.loads(args.manifest.read_text(encoding="utf-8"))
    root = Path(manifest["source_root"])
    if args.output.resolve() == root.resolve() or args.output.resolve().is_relative_to(root.resolve()):
        raise SystemExit("Export must be outside the supplied PDF folder")
    if not args.output.parent.is_dir():
        raise SystemExit("Export folder does not exist")
    with args.ledger.open(encoding="utf-8-sig", newline="") as stream:
        table = csv.DictReader(stream)
        fields = table.fieldnames or []
        rows = list(table)
    errors = []
    if not all(field in fields for field in FIELDS):
        errors.append({"row": None, "error": "Missing required CSV columns"})
    if not rows:
        errors.append({"row": None, "error": "No evidence rows to verify"})
    cache = {}
    for number, row in enumerate(rows, 2):
        try:
            if None in row or any(not (row.get(field) or "").strip() for field in FIELDS):
                raise ValueError("Missing field or malformed CSV row")
            if row["claim_type"] not in {"source_claim", "interpretation"}:
                raise ValueError("Invalid claim_type")
            if not row["limitation"].startswith(("Source:", "Analyst:")):
                raise ValueError("Label limitation attribution with Source: or Analyst:")
            if not row["limitation"].split(":", 1)[1].strip():
                raise ValueError("Limitation text is empty")
            citation = row["citation"]
            record = manifest["sources"].get(citation)
            if not record:
                raise ValueError("Citation is absent from supplied PDF inventory")
            page = int(row["page"])
            if page < 1 or row["page"] != str(page):
                raise ValueError("Page must be a positive integer")
            if citation not in cache:
                data = source_path(root, citation).read_bytes()
                if digest(data) != record["sha256"]:
                    raise ValueError("Original PDF changed since extraction")
                pdf = reader(data)
                if pdf.is_encrypted and not pdf.decrypt(""):
                    raise ValueError("PDF is encrypted")
                cache[citation] = pdf
            pdf = cache[citation]
            if page > len(pdf.pages):
                raise ValueError("Cited page does not exist")
            actual = normalized(pdf.pages[page - 1].extract_text() or "")
            if not actual or normalized(row["quoted_passage"]) not in actual:
                raise ValueError("Quotation does not match the cited original page")
        except Exception as error:
            errors.append({"row": number, "error": str(error)})
    report = {"provenance_valid": not errors, "row_count": len(rows), "errors": errors,
              "scope": "Checks source identity, page, quoted text, and fields; not claim accuracy, interpretation, or completeness"}
    if args.output.exists():
        raise SystemExit("Export already exists; use a new output path to avoid a stale result")
    json_write(args.output.parent / "verification.json", report)
    if errors:
        print(json.dumps(report, ensure_ascii=False))
        return 1
    with args.output.open("x", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields)
        writer.writeheader()
        writer.writerows(rows)
    print(json.dumps(report, ensure_ascii=False))
    return 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    inventory = commands.add_parser("extract")
    inventory.add_argument("source", type=Path)
    inventory.add_argument("work", type=Path)
    inventory.add_argument("--expected", action="append", default=[])
    gate = commands.add_parser("verify")
    gate.add_argument("manifest", type=Path)
    gate.add_argument("ledger", type=Path)
    gate.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.command == "extract":
        extract(args)
        return 0
    return verify(args)


if __name__ == "__main__":
    sys.exit(main())

