#!/usr/bin/env python3
"""Local PDF page packet preparation and conservative evidence CSV validation."""
import argparse
import csv
import hashlib
import json
import sys
from pathlib import Path

FIELDS = ['citation', 'page', 'quoted_passage', 'claim', 'limitation', 'claim_type', 'source_file']
ISSUES = ['issue', 'source_file', 'page', 'detail']


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def normalized(text):
    return ' '.join(text.split())


def prepare(args):
    root = Path(args.pdf_dir).resolve()
    out = Path(args.output_dir).resolve()
    if not root.is_dir():
        raise ValueError('PDF folder does not exist')
    if out == root or root in out.parents:
        raise ValueError('Output directory must be outside the source folder')
    out.mkdir(parents=True, exist_ok=True)
    if (out / 'pages.json').exists() or (out / 'issues.csv').exists():
        raise ValueError('Use a new output directory; existing packet/issues will not be overwritten')
    issues, sources = [], {}
    files = sorted(p for p in root.rglob('*') if p.is_file() and p.suffix.lower() == '.pdf')
    found = {p.relative_to(root).as_posix() for p in files}
    for name in args.expect:
        if name not in found:
            issues.append(['missing_pdf', name, '', 'Expected supplied PDF is absent'])
    if not files:
        issues.append(['no_pdfs', '', '', 'No supplied PDF files found'])
    try:
        from pypdf import PdfReader
    except ImportError:
        PdfReader = None
        issues.append(['extractor_unavailable', '', '', 'pypdf is not installed; no PDF pages extracted'])
    for path in files:
        name = path.relative_to(root).as_posix()
        try:
            path.resolve().relative_to(root)
        except ValueError:
            issues.append(['outside_corpus', name, '', 'Symlink resolves outside supplied folder'])
            continue
        try:
            source = {'sha256': digest(path), 'status': 'unreadable', 'pages': {}}
            sources[name] = source
            if PdfReader is None:
                continue
            reader = PdfReader(str(path))
            if reader.is_encrypted and not reader.decrypt(''):
                raise ValueError('Encrypted PDF requires a password')
            source['page_count'] = len(reader.pages)
            for number, page in enumerate(reader.pages, 1):
                try:
                    value = page.extract_text() or ''
                    status = 'readable' if value.strip() else 'unreadable'
                    source['pages'][str(number)] = {'status': status, 'text': value}
                    if status == 'unreadable':
                        issues.append(['unreadable_page', name, number, 'No extractable text; may require OCR'])
                    else:
                        source['status'] = 'readable'
                except Exception as error:
                    source['pages'][str(number)] = {'status': 'unreadable', 'text': ''}
                    issues.append(['unreadable_page', name, number, str(error)])
        except Exception as error:
            issues.append(['unreadable_pdf', name, '', str(error)])
    packet = {'schema_version': 1, 'pdf_root': str(root), 'sources': sources}
    (out / 'pages.json').write_text(json.dumps(packet, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    with (out / 'issues.csv').open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(ISSUES)
        writer.writerows(issues)
    usable = sum(p['status'] == 'readable' for s in sources.values() for p in s['pages'].values())
    print('Recorded {} supplied files, {} readable pages, {} issues. Review issues.csv.'.format(len(files), usable, len(issues)))
    return 0 if usable else 2


def verify(args):
    packet = json.loads(Path(args.packet).read_text(encoding='utf-8'))
    if packet.get('schema_version') != 1:
        raise ValueError('Unsupported packet schema')
    root = Path(packet['pdf_root']).resolve()
    errors, checked, hashes = [], 0, {}
    with Path(args.ledger).open(newline='', encoding='utf-8-sig') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != FIELDS:
            raise ValueError('CSV header must be exactly: ' + ','.join(FIELDS))
        for line, row in enumerate(reader, 2):
            checked += 1
            problems = []
            if None in row or any(not (row.get(k) or '').strip() for k in FIELDS):
                problems.append('all seven fields must be nonempty and correctly delimited')
            name = row.get('source_file') or ''
            source = packet['sources'].get(name)
            if row.get('citation') != name:
                problems.append('citation must equal the supplied relative filename')
            kind = row.get('claim_type')
            if kind not in ('source_claim', 'interpretation'):
                problems.append('invalid claim_type')
            if kind == 'interpretation' and not (row.get('claim') or '').startswith('Interpretation:'):
                problems.append('interpretation claim must begin with Interpretation:')
            page = row.get('page') or ''
            record = source.get('pages', {}).get(page) if source else None
            if not page.isdecimal() or int(page) < 1 or not record or record.get('status') != 'readable':
                problems.append('page is absent or unreadable in the packet')
            elif not normalized(row.get('quoted_passage') or '') or normalized(row['quoted_passage']) not in normalized(record['text']):
                problems.append('quote is not an exact passage on the cited page')
            if not source:
                problems.append('source not in supplied corpus')
            else:
                if name not in hashes:
                    try:
                        file = (root / name).resolve()
                        file.relative_to(root)
                        hashes[name] = file.is_file() and digest(file) == source['sha256']
                    except (OSError, ValueError, KeyError):
                        hashes[name] = False
                if not hashes[name]:
                    problems.append('source missing, outside corpus, or changed since extraction')
            errors.extend('row {}: {}'.format(line, message) for message in problems)
    if checked == 0:
        errors.append('No evidence rows: report unavailable evidence and issues; do not invent rows')
    if errors:
        print('\n'.join(errors), file=sys.stderr)
        return 1
    print('Validated {} rows for file/page/text provenance only; semantic and extraction review still required.'.format(checked))
    return 0


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='command', required=True)
    prep = commands.add_parser('prepare')
    prep.add_argument('pdf_dir')
    prep.add_argument('output_dir')
    prep.add_argument('--expect', action='append', default=[])
    check = commands.add_parser('verify')
    check.add_argument('packet')
    check.add_argument('ledger')
    args = parser.parse_args()
    try:
        return prepare(args) if args.command == 'prepare' else verify(args)
    except (OSError, ValueError, KeyError, TypeError) as error:
        print('Error: ' + str(error), file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())

